    'fc.help_body' => 'Gère les codes abrégés composés depuis le téléphone (comme <code>*78</code>) : Ne pas déranger (DND), renvoi d\'appel, interception d\'appel de groupe/dirigée, écoute discrète, connexion/déconnexion de file (<code>*81&lt;queue id&gt;</code> / <code>*80&lt;queue id&gt;</code>), pause / reprise de file (<code>*22&lt;break id&gt;</code> / <code>*23</code>).',
    'fc.help_body2' => 'Le <strong>code</strong> de chaque fonction (les codes normaux doivent commencer par <code>*</code>, ceux avec un paramètre variable par <code>_*</code>) et <strong>les rôles autorisés à l\'utiliser</strong> (vide = tout le monde) peuvent être modifiés. Le comportement lui-même (ce qu\'il fait) est fixe — aucun nouveau type de comportement ne peut être ajouté, seuls ces codes sont modifiables.',
