    'asterisk_settings.rtp_section_title' => 'Paramètres RTP (média)',
    'asterisk_settings.rtp_help_body' => 'Détermine la plage de ports qui transporte l\'audio (RTP) et si Asterisk rejette l\'audio provenant d\'une source inattendue. Ce fichier (<code>/etc/asterisk/rtp.conf</code>) est désormais généré par le panneau ; les modifications manuelles sur le serveur sont perdues au prochain « Appliquer ».',
    'asterisk_settings.field_rtp_start' => 'Port RTP de début',
    'asterisk_settings.rtp_start_help' => 'Début de la plage de ports réservée aux flux audio. Chaque appel simultané consomme des ports de cette plage.',
    'asterisk_settings.field_rtp_end' => 'Port RTP de fin',
    'asterisk_settings.rtp_end_help' => 'Fin de la plage. coturn (relais TURN) utilise 13479-14999 — un chevauchement casse l\'audio WebRTC et est refusé à l\'enregistrement.',
    'asterisk_settings.field_rtp_strict' => 'RTP strict (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Lorsque cette option est activée, Asterisk ignore silencieusement l\'audio provenant de toute source autre que l\'adresse/le port distant appris (protection contre les attaques). Si le PBX distant envoie le média depuis un port inattendu, cela provoque une panne silencieuse « pas d\'audio » sans aucune trace dans les journaux — l\'option peut être désactivée temporairement pour le diagnostic.',
    'asterisk_settings.rtp_strict_yes' => 'Activé (recommandé)',
    'asterisk_settings.rtp_strict_no' => 'Désactivé (pour le diagnostic)',
    'asterisk_settings.rtp_restart_warning' => 'Le paramètre RTP strict prend effet avec « Appliquer ». En revanche, une modification de la PLAGE DE PORTS nécessite un redémarrage complet d\'Asterisk — le pool de ports est alloué une seule fois au chargement du module.',
    'asterisk_settings.udptl_section_title' => 'Paramètres T.38 UDPTL (média fax)',
    'asterisk_settings.udptl_help_body' => 'Définit les plages de ports UDP et les paramètres de correction d\'erreurs (FEC / somme de contrôle) des paquets fax T.38 (UDPTL). Ce fichier (<code>/etc/asterisk/udptl.conf</code>) est géré dynamiquement.',
    'asterisk_settings.field_udptl_start' => 'Port UDPTL de début',
    'asterisk_settings.udptl_start_help' => 'Port UDP de début pour les flux fax T.38 (par défaut : 4100).',
    'asterisk_settings.field_udptl_end' => 'Port UDPTL de fin',
    'asterisk_settings.udptl_end_help' => 'Port UDP de fin pour les flux fax T.38 (par défaut : 4999).',
