    'trunks.field_connection_mode' => 'Mode de connexion',
    'trunks.connection_mode_ip' => 'Par IP (le pair a une IP statique)',
    'trunks.connection_mode_register' => 'Enregistrement entrant (le pair s\'enregistre auprès de nous)',
    'trunks.connection_mode_help' => 'Par IP : le pair est identifié par son adresse IP et son contact reste statique — mode recommandé pour un pair à IP fixe sur le même réseau. Enregistrement entrant : le pair nous envoie un SIP REGISTER et son adresse est apprise à partir de cet enregistrement. Ce mode nécessite un nom d\'utilisateur et un mot de passe, avec lesquels le pair authentifie à la fois son enregistrement et ses appels.',
    'trunks.connection_mode_warning' => 'Le passage en mode enregistrement supprime le contact statique : nous ne pouvons pas appeler ce trunk TANT QUE le pair ne s\'est pas enregistré auprès de nous. Effectuez ce changement en même temps que le réglage d\'enregistrement côté pair.',
