    'sound_packs.title' => 'Packs de sons officiels d\'Asterisk',
    'sound_packs.help_title' => 'Packs de sons Asterisk',
    'sound_packs.help_body' => 'Télécharge et installe les messages système et la musique d\'attente officiels d\'Asterisk depuis <code>downloads.asterisk.org</code>. Chaque pack correspond à une langue dans un format ; Asterisk lit le format correspondant au codec de l\'appel et transcode sinon (g722 pour G.722, ulaw/alaw pour les opérateurs).<br>- <strong>Core :</strong> messages système, chiffres, messagerie vocale. <strong>Extra :</strong> messages supplémentaires ; le pack core de la même langue doit être installé au préalable.<br>- <strong>Musique d\'attente (opsound) :</strong> installée dans <code>/var/lib/asterisk/moh/opsound</code> ; pour la diffuser, créez une classe MOH nommée <strong>opsound</strong> dans l\'onglet Musique d\'attente.<br>- <strong>Türkçe (AiPBX) :</strong> les messages turcs propres à AiPBX (release GitHub, vérifiés par SHA256) ; la langue par défaut étant le turc, leur suppression rend muets les messages système. La suppression n\'efface que les fichiers installés par le pack.',
