    'ms_teams.guide_title' => 'Guide d\'intégration Microsoft Teams',
    'ms_teams.guide_intro' => 'AiPBX peut communiquer avec Microsoft Teams à deux niveaux différents :',
    'ms_teams.guide_dr_title' => '1. Direct Routing (SBC / trunk SIP) :',
    'ms_teams.guide_dr_desc' => 'Permet aux utilisateurs Teams de passer et recevoir des appels internes et externes directement depuis le clavier de Teams sur ordinateur/mobile. Nécessite TLS (port 5061), SRTP et un certificat SSL public valide (ex. Let\'s Encrypt).',
    'ms_teams.guide_webhook_title' => '2. Webhooks et notifications de canal :',
    'ms_teams.guide_webhook_desc' => 'Envoie des cartes adaptatives (Adaptive Cards) interactives vers les canaux Teams désignés pour les appels manqués, messages vocaux, fax entrants et alertes du centre d\'appels. Ne nécessite pas de licence de téléphonie.',
    'ms_teams.guide_ps_title' => '3. Générateur PowerShell automatisé :',
