    'certificates.header_title' => 'Certificat TLS',
    'certificates.help_title' => 'Guide des certificats',
    'certificates.help_body' => 'Le portail (HTTPS), WebRTC TURNS et SIP-TLS/WSS partagent un même certificat ; les modifications effectuées ici sont appliquées ensemble à Apache, coturn et Asterisk. <b>Let\'s Encrypt</b> est gratuit et se renouvelle automatiquement ; le domaine doit pointer vers ce serveur et le port 80 doit être accessible depuis Internet. Si votre organisation dispose d\'un certificat, <b>importez-le</b> (PEM ou PFX) ; les certificats importés ne se renouvellent pas automatiquement, importez-en un nouveau avant son expiration. Avec un certificat <b>auto-signé</b>, les navigateurs affichent un avertissement et TURNS ne fonctionne pas dans les navigateurs : les appels WebRTC derrière des pare-feu peuvent être sans audio.',
