    'sidebar.item_queue_reports' => 'Centre de rapports des files d\'attente',
    'queue_reports.title' => 'Centre de rapports des files d\'attente',
    'queue_reports.help_title' => 'Guide des rapports de files d\'attente',
    'queue_reports.help_body' => 'Chaque appel entrant dans une file d\'attente est compté une seule fois. <b>Répondu</b> : mis en relation avec un agent. <b>Perdu</b> : l\'appelant a raccroché pendant l\'attente ou le délai de la file d\'attente a expiré. <b>Abandon court</b> : raccroché dans les %d secondes ; exclu du niveau de service. <b>Niveau de service</b> : appels répondus dans l\'objectif, sur l\'ensemble des appels hors abandons courts. <b>ASA</b> : attente moyenne des appels répondus. <b>AHT</b> : durée moyenne de conversation. <b>Taux de prise</b> (agent) : fréquence à laquelle l\'agent a répondu lorsque la file d\'attente l\'a fait sonner. <b>Rappel</b> : un appel perdu est considéré comme résolu lorsque son numéro a ensuite été appelé depuis un poste, ou a rappelé et obtenu une réponse. Les données proviennent du journal des files d\'attente d\'Asterisk ; le rapport peut être téléchargé en PDF ou Excel.',
    'queue_reports.all_queues' => 'Toutes les files d\'attente',
    'queue_reports.sl_target' => 'Objectif de niveau de service',
