    'ai_tts.title' => 'TTS cloud (synthèse vocale)',
    'ai_tts.help_title' => 'Guide du TTS cloud',
    'ai_tts.help_body' => 'Transforme du texte en voix naturelle grâce à des services cloud (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Écoutez le résultat, téléchargez-le en MP3 ou enregistrez-le en un clic comme <b>annonce</b> : il est converti au format d\'Asterisk (WAV 8 kHz) et ajouté à Sons &amp; annonces pour les IVR, routes entrantes et conditions horaires (prise en compte après Appliquer). <b>Ces services sont payants</b> et facturés au caractère ; chaque synthèse est conservée dans l\'historique avec son nombre de caractères. Les clés d\'accès proviennent de la console de chaque fournisseur, sont stockées chiffrées et ne sont plus jamais affichées sur la page.',
