    'ai_tts.provider_hint_polly' => 'Dans AWS IAM, créez une clé d\'accès pour un utilisateur ne disposant que de « polly:SynthesizeSpeech » et « polly:DescribeVoices ». Jusqu\'à %s caractères par requête.',
    'ai_tts.provider_hint_azure' => 'Créez une ressource « Speech » dans le portail Azure ; la clé et la région (ex. westeurope) figurent sur sa page « Keys and Endpoint ». Jusqu\'à %s caractères par requête.',
