    'push.help_intro' => 'Le softphone mobile AI PBX dispose d\'une <strong>architecture de notifications en couches</strong> :',
    'push.help_layer0' => '<strong>Couche 0 (sans dépendance - par défaut) :</strong> une connexion WSS persistante, un service de premier plan <code>specialUse</code> compatible Android 15 et un watchdog <code>AlarmManager</code> résistant au mode Doze qui le relance. Aucun service externe n\'est nécessaire ; les appels arrivent même lorsque l\'appareil est en veille ou l\'écran éteint.',
    'push.help_layer1' => '<strong>Couche 1 (facultative - Google FCM) :</strong> une garantie de réveil supplémentaire sur les appareils de constructeurs aux restrictions de batterie agressives (Xiaomi, Huawei...) ou lorsque l\'utilisateur a fermé l\'application par glissement. <em>Elle ne se déclenche que lorsque le poste n\'a pas d\'enregistrement SIP actif, les postes enregistrés ne subissent donc aucun délai.</em>',
    'push.help_no_fcm' => 'Si vous ne souhaitez pas utiliser FCM, laissez le fournisseur sur <strong>« Local (sans dépendance) »</strong>. L\'application mobile n\'établit alors aucun contact réseau avec Google.',
