    'mailtpl.invite_new.subject' => '[{brand}] Votre compte a été créé - définissez votre mot de passe',
    'mailtpl.invite_new.body' => '<p>Bonjour {name},</p>{mobile_section}<p>Votre compte sur l’autocommutateur <strong>{brand}</strong> est prêt. Pour vous connecter, définissez votre mot de passe avec le bouton ci-dessous.</p>{account_details}{reset_button}<p>Si le bouton ne fonctionne pas, ouvrez ce lien : {reset_link}</p><p><em>Le lien de mot de passe est valable 48 heures et ne fonctionne qu’une fois. Si vous n’attendiez pas cet e-mail, contactez votre administrateur système.</em></p>',
    'mailtpl.invite.subject' => '[{brand}] Votre lien de connexion et de mot de passe',
    'mailtpl.invite.body' => '<p>Bonjour {name},</p>{mobile_section}<p>Voici un nouveau lien pour définir votre mot de passe sur <strong>{brand}</strong>.</p>{account_details}{reset_button}<p>Si le bouton ne fonctionne pas, ouvrez ce lien : {reset_link}</p><p><em>Le lien de mot de passe est valable 48 heures et ne fonctionne qu’une fois. Si vous ne l’avez pas demandé, contactez votre administrateur système.</em></p>',
    'mailtpl.password_reset.subject' => '[{brand}] Réinitialisez votre mot de passe',
    'mailtpl.password_reset.body' => '<p>Bonjour {name},</p><p>Une réinitialisation du mot de passe a été demandée pour votre compte <strong>{username}</strong>.</p>{reset_button}<p>Si le bouton ne fonctionne pas, ouvrez ce lien : {reset_link}</p><p><em>Le lien est valable 30 minutes. Si vous ne l’avez pas demandé, ignorez cet e-mail ; votre mot de passe reste inchangé.</em></p>',
    'mailtpl.voicemail.subject' => 'Nouveau message vocal de {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Bonjour {name},</p><p>Vous avez un nouveau message vocal dans la boîte <strong>{mailbox}</strong>.</p><ul><li><strong>De :</strong> {caller}</li><li><strong>Reçu :</strong> {date}</li><li><strong>Durée :</strong> {duration}</li></ul><p>Si l’enregistrement est joint, vous pouvez l’écouter directement ici. Vous pouvez aussi l’écouter dans le portail ({portal_link}) ou en composant le *97.</p>',
    'mailtpl.fax_received.subject' => 'Nouveau fax reçu - {department} ({did})',
    'mailtpl.fax_received.body' => '<p>Un nouveau fax a été reçu.</p><ul><li><strong>Service :</strong> {department}</li><li><strong>Numéro de fax :</strong> {did}</li><li><strong>De :</strong> {caller}</li><li><strong>Pages :</strong> {pages}</li><li><strong>Reçu :</strong> {date}</li></ul><p>Le fax est joint en PDF lorsque cette option est activée. Tous les fax se trouvent dans la boîte de réception des fax : {portal_link}</p>',
