    'storage.in_use_s3' => 'Utilisé : bucket S3',
    'storage.help_title' => 'Où sont conservés les fichiers du chat',
    'storage.help_body' => '<p>Les pièces jointes du chat, leurs miniatures et les images de groupe sont stockées par défaut sur le disque du serveur (<code>/var/lib/aipbx/chat_files</code>). Avec un stockage compatible S3 (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …), elles vont dans un bucket et les gros fichiers ne restent pas sur le PBX.</p><p>Les téléchargements passent toujours par le service de chat, donc seuls les participants d\'un chat peuvent ouvrir ses fichiers ; le bucket peut rester privé. Les fichiers stockés avant le changement sont toujours servis depuis le disque jusqu\'à ce que vous les déplaciez. Les paramètres du bucket sont vérifiés avant d\'être enregistrés.</p><p>Les enregistrements d\'appels, la messagerie vocale et les fax restent sur le disque local.</p>',
