    'netsvc.help_title' => 'Services réseau',
    'netsvc.help_body' => 'Les téléphones de bureau trouvent seuls le serveur de provisioning lorsque le serveur DHCP distribue son adresse (option 66). DHCP et TFTP s\'activent séparément. Avec le <strong>serveur DHCP</strong> désactivé, votre propre serveur DHCP reste en place : configurez-y les options listées ci-dessous. Activé, AiPBX distribue des adresses sur une interface ou un VLAN. Le <strong>serveur TFTP</strong> sert les fichiers de démarrage et le firmware que vous téléversez. La configuration de chaque téléphone (avec le mot de passe SIP) est toujours servie en HTTPS, jamais en TFTP.',
