    'web_widgets.help_title' => 'Widget d\'appel pour site web et formulaire de rappel',
    'web_widgets.help_body' => 'Un widget place un bouton « Appelez-nous » sur n\'importe quel site web. Les visiteurs vous parlent depuis le navigateur via WebRTC, ou laissent leur numéro et le PBX les rappelle. Collez le code d\'une ligne dans le site web (ou dans le plugin WordPress), puis cliquez sur <strong>Appliquer</strong> après l\'enregistrement.',
    'web_widgets.help_number' => 'Numéro :',
    'web_widgets.help_number_desc' => 'Un widget entre dans le PBX comme un trunk. Son numéro est le DID de ces appels dans les rapports et le CDR ; le visiteur ne choisit jamais où va l\'appel.',
    'web_widgets.help_security' => 'Sécurité :',
    'web_widgets.help_security_desc' => 'Seuls les sites web autorisés peuvent utiliser le widget. Chaque appel nécessite un jeton à usage unique, et les limites (par IP, par jour, appels simultanés, durée d\'appel) s\'appliquent à chaque requête. Chaque requête est journalisée ci-dessous.',
    'web_widgets.help_callback' => 'Rappel :',
    'web_widgets.help_callback_desc' => 'Le PBX compose le numéro du visiteur via la route sortante choisie et, lorsqu\'il répond, l\'envoie vers la destination. Seuls les numéros commençant par les préfixes autorisés sont appelés, et une limite quotidienne est obligatoire.',
    'web_widgets.help_wordpress' => 'WordPress :',
